import 'dart:convert';
import 'dart:typed_data';

import 'package:flutter/material.dart';

/// Official ScamShield guardian brand mark. Embedded for reliable offline use.
class ScamShieldBrandMark extends StatelessWidget {
  final double size;
  final BorderRadius borderRadius;

  const ScamShieldBrandMark({
    super.key,
    this.size = 54,
    this.borderRadius = const BorderRadius.all(Radius.circular(14)),
  });

  static Uint8List? _bytes;
  static Uint8List get bytes => _bytes ??= base64Decode(_logoBase64);

  @override
  Widget build(BuildContext context) {
    return ClipRRect(
      borderRadius: borderRadius,
      child: Image.memory(
        bytes,
        width: size,
        height: size,
        fit: BoxFit.cover,
        filterQuality: FilterQuality.high,
        gaplessPlayback: true,
        semanticLabel: 'ScamShield African guardian logo',
      ),
    );
  }
}

